#!/usr/bin/env python3
"""Build the conventions for the two active SOP semantic families."""
from pathlib import Path
import json
import subprocess
import html
ROOT=Path(__file__).resolve().parent.parent
DOCS=ROOT/'docs'
esc=html.escape
pages=[('index','Overview'),('clause-sop','Clause-SOP'),('event-sop','Event-SOP'),('sop-lng','Shared syntax'),('judge','Judge'),('repair','Repair'),('symbolic','Symbolic-first')]
def code(s): return '<pre><code>'+esc(s)+'</code></pre>'
def table(head,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def write(slug,title,lead,body):
 nav=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if s==slug else '')+'>'+label+'</a>' for s,label in pages)
 (DOCS/(slug+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · LLM Formaliser</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html">LLM Formaliser <span>Two semantic families · one SOP syntax</span></a><nav aria-label="Documentation">{nav}</nav></header><main id="main"><p class="eyebrow">SOP LANG / PHASED TASKS / BATCHING</p><h1>{esc(title)}</h1><p class="lead">{esc(lead)}</p>{body}</main><footer>Domain-specific prompts and converters live in llmFormaliser. Ploinky Workers remains a generic phased executor.</footer></body></html>')
flow='<div class="flow"><span>begin · BATCH · small</span><span>toCnl · INDIVIDUAL · local code</span><span>judge · BATCH · best</span><span>finish · INDIVIDUAL · local code</span></div>'
write('index','Two SOP formalizers, one execution flow','Six task types: two baselines, two selective repairs and two symbolic-first repairs. One explicit flush executes the complete experiment.',flow+
 '<div class="grid"><a class="card" href="clause-sop.html"><h2>Clause-SOP</h2><p>CNL-E prototype semantics: grammatical participants, assertion status and local modifiers, written directly as SOP.</p></a><a class="card" href="event-sop.html"><h2>Event-SOP</h2><p>Event IR prototype semantics: semantic roles, scoped operators, quantification and discourse records, written directly as SOP.</p></a></div>'+
 '<h2>The batching advantage</h2><p>For ten compatible tasks, begin sends one combined model request. Each returned result is assigned to its own task. Ten local conversions then run on ten separate states. Ready judge phases batch again. Ten individual finish phases validate and persist their own results. The caller enqueues full tasks once and calls flush once; it does not reconstruct this workflow with separate API loops.</p>'+
 '<div class="note">The worker test with ten independent inputs asserts exactly two fake model calls and forty phase executions. Different prompt prefixes, response arrival times, model errors or configured batch limits can create additional batches. Local state is never shared.</div>'+
 '<p>All six workflow files are listed in the <a href="../README.md">README</a>.</p><h2>Task files</h2><p>Markdown uses level-two headings for phases and level-three headings for every field. Prompt and JavaScript blocks are literal, without JSON string escapes.</p><ul><li><a href="../taskTypes/formalise_clause-judge.md">formalise_clause-judge.md</a></li><li><a href="../taskTypes/formalise_event-judge.md">formalise_event-judge.md</a></li></ul><p>These baseline files contain begin, toCnl, judge and finish. Each dialect also has a selective-repair and symbolic-first workflow; all six use the same canonical dialect and judge files.</p>'+
 '<h2>Canonical prompt files</h2><p>Every generation and repair phase includes the same dialect file: lib/prompts/clause-sop.txt or lib/prompts/event-sop.txt. Includes use ${{lib/prompts/clause-sop.txt}} and expand before batching. Only the final input argument is variable. Scalars can be written as ### tier:small or ###next:repair. Experiment snapshots freeze and hash included files.</p><h2>Execution policy belongs in configuration</h2><p><a href="../pworker.config.json">pworker.config.json</a> keeps cache enabled and the selected model fixed. No maxTokens or temperature is imposed. Task types contain phase logic, tier and batching declarations. Local phases contain explicit code with library imports, conversion calls, pair construction and result writes. Libraries execute in the worker sandbox; codeFile is forbidden.</p>'+
 '<p><a href="../README.md">Commands and experiment records</a> · <a href="../experiments/initial-10.json">Initial 10 examples</a> · <a href="sop-lng.html">Shared wire syntax</a> · <a href="judge.html">Judge conventions</a> · <a href="repair.html">Selective repair</a> · <a href="symbolic.html">Symbolic-first repair</a></p>')

write('sop-lng','Shared SOP Lang syntax','One declaration per line; shared notation does not erase differences between the two semantic models.',
 code('@eventId TYPE key=value key=value ...')+
 table(['Notation','Convention'],[('@id','Unique declaration identifier.'),('$id','Reference to an existing declaration; forward references are allowed.'),('key=value','Fields attach to the declared record. No bracket wrapper around the whole declaration.'),('[a,b]','Ordered list value. The Event IR prototype also accepts comma lists.'),('@m1 MOD target=$e1 label=time value=now','A separate SOP line attaches a modifier; no inline objects.'),('"quoted value"','Quote spaces and ambiguous strings. Numeric quantities may be bare or quoted.'),('E / EV / p / st / t','Shared entity/event, predicate, assertion-status and tense concepts.'),('subj / obj versus ag / th','Grammatical participants are not automatically semantic agent/theme roles.'),('neg / MOD versus OP / root / sc','Local CNL-E negation/modality differs from explicit Event IR operator chains.')])+
 '<h2>Validation</h2><p>Failed conversions expose an errors array with independent diagnostics, record IDs, fields and source line numbers where known. The repair phase receives every collected diagnostic once. Syntax recovery continues across independent lines and fields; structural checks run only after syntax and references are reliable, avoiding cascades from partial records. Validation does not silently repair the source or establish semantic equivalence.</p><p>The shared parser rejects duplicate IDs, repeated scalar fields, malformed values and unresolved explicit references. Event-SOP PS.exists is list-valued: repeated exists fields are collected without dropping targets, recorded in normalization metadata and rendered as separate existence presuppositions. Clause-SOP validates its grammatical schema. Event-SOP validates the native typed graph and preserves every supplied field in CNL, including annotations. OP, Q, QS and L are legal reference targets; numeric values remain literals. Spelling conventions produce warnings rather than semantic rejection. A single batch-ID wrapper can be extracted losslessly, with provenance; active formalizations reject inline objects. Historical replay can explicitly opt into the archived spelling normalizer, recording each edit. Numeric modifier values remain numbers and numeric lexical units such as 10000_euro remain strings. Invalid formalizations skip the model judge and proceed to finish with an explicit failure.</p><p>Original prototype adapters and regression fixtures remain in lib/vendor for reference; six workflow files share two canonical dialect prompts.</p>')
for slug,title,lead,rows,sample in [
 ('clause-sop','Clause-SOP','CNL-E semantics translated into SOP syntax, without separate bracket/JSON/KV variants.',[
 ('E','Noun record: q, adj, plural; noun modifiers use MOD target=$noun.'),('EV','Event: p, subj, obj, st, neg, t, flags; event modifiers use MOD target=$event.'),('st','asserted (default), unasserted, queried, directive or expressive.'),('embed=true','Marks an embedded question when st=queried.'),('t / flags','past/present/future tense; PERF, PROG, HABIT, POLITE and EMPH flags.'),('MOD','Separate declaration: target, label, value; optional neg=true negates the modifier.'),('formula / logic + args','Mathematical statements or either/both/not over event references.'),('G','Separate participant group: t=and|or|alt|only|even|also and m=[...]. Participants reference its ID.'),('DISC / UM','Pragmatic/discourse wording: DISC t=function span=original with optional target; UM retains uninterpreted source wording without inventing a meaning.')],
 '@E1 EV st=asserted subj=John p=say obj=$E2 t=past\n@E2 EV st=unasserted subj=Mary p=leave t=past'),
 ('event-sop','Event-SOP','Event IR SOP v5 semantics: typed roles, scope, discourse and ambiguity.',[
 ('S / E','One discourse-level sentence/speech-act record and entity declarations.'),('EV / ST / RE / EX / ID / DF / CP','Event, state, relation, existence, identity, definition and comparison frames.'),('p / ag / th / ct / st / t','Predicate, semantic participants/content, status and tense.'),('OP / root / sc','Separate operators and explicit outermost/root and scope links.'),('L / ER / G / QS / LS','Frame/entity links, logical groups and quantifier/logical scope.'),('DISC','Pragmatic/discourse function and original span; optional target scopes it to a proposition.'),('PS / CI / CX / MN / AM / MS / UM / Q','Presupposition, implicature, context, mentions, ambiguity, missing/unmapped content and questions.')],
 '@s1 S\n@x1 E h=person ty=person n=John\n@e1 EV p=leave ag=$x1 root=$o2\n@o1 OP t=negation sc=$e1\n@o2 OP t=deontic v=required sc=$o1')]:
 short=slug.removesuffix('-sop')
 task=json.loads(subprocess.check_output(['node','--input-type=module','-e', 'import {loadTask} from \"../Ploinky-Worker/lib/pworker/task.mjs\"; console.log(JSON.stringify(await loadTask(process.argv[1])));', str(ROOT/'taskTypes'/('formalise_'+slug.removesuffix('-sop')+'-judge.md'))],cwd=ROOT,text=True))
 body=flow+'<h2>Conventions</h2>'+table(['Record / field','Meaning'],rows)+'<h2>Example</h2>'+code(sample)
 body+='<h2>Four phases in this file</h2>'+table(['Phase','Execution'],[('begin','Batchable small-tier formalization, returning SOP text.'),('toCnl','Individual sandboxed library code: validate and reconstruct CNL; save this task’s artifact.'),('judge','Batchable best-tier equivalence check using only this task’s source/CNL pair.'),('finish','Individual local verdict validation and final artifact; no model call.')])
 body+='<h2>Discourse without invented emotion</h2><p>Markers such as basically may signal approximation or summarization; they are not automatically emotions. DISC records retain their wording and contextual function separately from factual events. An omitted target denotes whole-utterance scope. UM or an unspecified function preserves uncertain material without guessing. Surface coverage alone does not prove semantic preservation.</p>'+code('@d1 DISC target=$e1 t=approximation span=basically\n@d2 DISC target=$e1 t=discourse-marker span=Well')
 body+='<h2>Local phase code</h2><h3>toCnl</h3>'+code(task['toCnl']['code'])+'<h3>finish</h3>'+code(task['finish']['code'])
 if slug=='clause-sop': body+='<p>Present tense is the declared default when the SOP t field is absent; the CNL renderer makes this explicit. Only past and future require t.</p>'
 body+='<h2>Prompt provenance</h2><p>'+('CNL-E rules are adapted to SOP fields, and all 64 original examples are mechanically translated to the same syntax. Core event distinctions are preserved; the original filler-removal rule has been replaced by explicit DISC/UM records. The three affected prototype examples have explicit discourse annotations.' if slug=='clause-sop' else 'The Event IR SOP v5 rules are adapted in the canonical Event-SOP text file, with a whole-input discourse convention and the worker batch-envelope instruction.')+'</p>'
 if slug=='event-sop': body+='<h2>Native graph conversion</h2><p>The converter no longer passes SOP through the narrower legacy v4 IR. CNL records display typed references and all fields. Question targets, embedded content and scoped operands are not independently asserted by default; explicit statuses remain visible. Incomplete comparisons remain incomplete for the judge, without inventing a minimum or maximum. Structural acceptance is distinct from semantic equivalence.</p>'
 body+=f'<p>Canonical generation and repair prompt: <a href="../lib/prompts/{slug}.txt">lib/prompts/{slug}.txt</a>. Both phases include this same file with the worker constant-file include syntax.</p>'
 body+=f'<p><a href="../taskTypes/formalise_{short}-judge.md">Complete four-phase task</a> · <a href="../lib/{slug}.mjs">Local converter source</a> · <a href="judge.html">Judgment criteria</a></p>'
 body+='<details><summary>Formalization prompt</summary>'+code((ROOT/'lib/prompts'/(slug+'.txt')).read_text())+'</details>'
 write(slug,title,lead,body)
write('judge','The shared judge phase','All six task types include the same judge.txt file; it is not a separate task.',flow+
 table(['Check','Meaning'],[('source_entails_cnl','No unsupported additions.'),('cnl_entails_source','No omissions of source meaning.'),('speech_act_preserved','Preserve assertion, question, command, request or expressive force.'),('ambiguity_preserved','Do not silently choose an unresolved reading.'),('verdict','equivalent, different or uncertain, consistent with the individual checks.'),('mismatches / explanation','Precise discrepancies and concise supporting evidence.')])+
 '<h2>Success</h2><p>Two yes entailments, two true preservation fields, no mismatches and an equivalent verdict are required. Invalid JSON, contradictory fields and uncertainty are not success. Every selected example remains in the denominator.</p>'+
 '<h2>Data isolation</h2><p>Each judge input is built by its own preceding local conversion. The model sees a batch envelope with separate IDs; pworker routes each judgment back to its originating task. Each finish phase validates and writes only that task’s result.</p><p>Questions use answer conditions and directives use compliance conditions, not asserted occurrence. Judgments are estimates, not logical proofs.</p><p><a href="../lib/prompts/judge.txt">Shared judge prompt</a> · <a href="../lib/judge.mjs">Local verdict validation</a></p>')
for stale in ['cnl-e.html','cnl-json.html','cnl-kv.html','sop-v5.html']:(DOCS/stale).unlink(missing_ok=True)
print('Built convention pages for the SOP families and their baseline, repair and symbolic-first workflows.')

write('repair','Selective single-pass repair','Separate task types preserve the baseline formalizer prompt and add one repair attempt.',
 '<p><a href="index.html">Index</a></p><p>begin (batch) → toCnl (individual) → judge (batch when needed) → review (individual). A failed candidate enters repair (batch), then conversion and selective judging again. finish writes every attempt. Repair is limited to one pass per case. Its separate repair tier can select a different model with --repair-provider and --repair-model; the judge remains unchanged before and after repair.</p><p>Local structural or numeric problems skip the initial judge and become repair feedback. Valid semantic differences include the judge’s specific feedback. Inconclusive or malformed judgments do not trigger speculative rewriting. Successful cases skip repair.</p><p>Exact source/CNL pairs can reuse a prior valid judgment only with the same model, judge prompt and validator. Conflicting cached judgments are excluded. Unchanged repaired candidates reuse their own previous judgment. Lexical coverage alone never establishes equivalence.</p><p>Baseline and repair scores are reported separately; raw attempts and feedback remain in the run artifacts. Dictionary-based selection restrictions are not yet implemented.</p>')

write('symbolic','Symbolic-first SOP drafts','Two additional experimental task types; the two dialect conventions are shared by every generation and repair phase.',
 '<p><a href="index.html">Index</a></p><p>Local discourse draft → local diagnostics → deterministic CNL → cached/fresh judgment for complete drafts → repair only if needed → individual finish.</p>'
 '<p>symbolicformalise_clause-symboliccheck-repair-judge.md and symbolicformalise_event-symboliccheck-repair-judge.md share a newly written, conservative clause parser and have separate SOP exporters. No implementation was copied from nlpFormaliser. The parser recognizes a limited lexical inventory, noun phrases, finite verbs, auxiliary negation/aspect, simple questions/directives, attitude complements and some coordination. Unsupported constructions and unresolved complements remain UM records with source spans in the draft artifact; role and scope uncertainty is reported to the repairer.</p>'
 '<p>A complete candidate reaches judgment first. Accepted candidates never enter repair. Exact accepted cached source/CNL pairs skip both judgment and repair, even when construction had uncertainty notes. Structural failures or unresolved draft diagnostics go directly to repair; a negative semantic judgment also triggers repair. Inconclusive judgments are not grounds for speculative rewriting. The model receives the authoritative source, complete SOP draft, accumulated structural diagnostics, approximate lexical checks and unresolved-fragment notes. Incomplete initial candidates remain unjudged; complete drafts have their own recorded assessment. Final candidates use the existing converters and judge prompt. Incomplete or structurally invalid final results cannot succeed.</p>'
 '<p>begin and draftCheck contain explicit individual code; toCnl converts and checks exact cached judgments; judge uses the best tier; review evaluates each task’s conditions before routing to repair or finish. Repair uses its configured tier and is limited to one pass. No small-tier formalizer is configured or called. All complete tasks are enqueued before one flush. Wave scheduling waits for active phases and local conditions within that run before batching the next cohort. Accepted tasks cannot join repair merely because another task failed.</p>'
 '<p>Artifacts retain the common clause graph, original spans, SOP draft, exact repair input, diagnostics, final SOP/CNL and judgments. Approximate declaration overlap compares literal values, fields, polarity and tense while ignoring reference names. It is not semantic reuse, and empty drafts have undefined retention. More complete modeling of quantifier scope, passive voice, attachments and reference resolution remains outside this conservative prototype.</p>')
